CREATE DATABASE IF NOT EXISTS review_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE review_db;
CREATE TABLE reviews (id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, variant_id BINARY(16), customer_id BINARY(16) NOT NULL, order_id BINARY(16) NOT NULL, rating TINYINT UNSIGNED NOT NULL, title VARCHAR(300), body TEXT NOT NULL, status ENUM('PENDING','PUBLISHED','REJECTED','HIDDEN') NOT NULL DEFAULT 'PENDING', verified_purchase BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_review_customer_order_variant(customer_id,order_id,variant_id), KEY ix_review_product_status_created(product_id,status,created_at), CONSTRAINT ck_review_rating CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE review_images (id BINARY(16) NOT NULL, review_id BINARY(16) NOT NULL, storage_key VARCHAR(1024) NOT NULL, sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_review_image_review(review_id,sort_order), CONSTRAINT fk_review_image_review FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE review_moderation (id BINARY(16) NOT NULL, review_id BINARY(16) NOT NULL, sentiment_score DECIMAL(6,5), toxicity_score DECIMAL(6,5), decision ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', reason VARCHAR(500), reviewed_by BINARY(16), reviewed_at TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_moderation_review(review_id), KEY ix_moderation_decision(decision), CONSTRAINT fk_moderation_review FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE product_rating_projection (product_id BINARY(16) NOT NULL, review_count INT UNSIGNED NOT NULL DEFAULT 0, average_rating DECIMAL(3,2) NOT NULL DEFAULT 0, rating_1_count INT UNSIGNED NOT NULL DEFAULT 0, rating_2_count INT UNSIGNED NOT NULL DEFAULT 0, rating_3_count INT UNSIGNED NOT NULL DEFAULT 0, rating_4_count INT UNSIGNED NOT NULL DEFAULT 0, rating_5_count INT UNSIGNED NOT NULL DEFAULT 0, updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(product_id), CONSTRAINT ck_rating_average CHECK(average_rating BETWEEN 0 AND 5)) ENGINE=InnoDB;
CREATE TABLE outbox_event (id BINARY(16) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, occurred_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at TIMESTAMP(6), attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_outbox_unpublished(published_at,occurred_at)) ENGINE=InnoDB;
